import{_ as l,o as i,c as a,O as o}from"./chunks/framework.db831a78.js";const P=JSON.parse('{"title":"计算机网络","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/07-计算机网络.md","filePath":"interview/后端/Java/07-计算机网络.md","lastUpdated":null}'),t={name:"interview/后端/Java/07-计算机网络.md"};function s(r,e,n,T,d,c){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="计算机网络" tabindex="-1">计算机网络 <a class="header-anchor" href="#计算机网络" aria-label="Permalink to &quot;计算机网络&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="http1-1-http2-http3-区别-★★★" tabindex="-1">HTTP1.1 / HTTP2 / HTTP3 区别 ★★★ <a class="header-anchor" href="#http1-1-http2-http3-区别-★★★" aria-label="Permalink to &quot;HTTP1.1 / HTTP2 / HTTP3 区别 ★★★&quot;">​</a></h2><ul><li>HTTP1.1：长连接、管道化，但队头阻塞、无压缩头部、明文。</li><li>HTTP2：二进制分帧、多路复用（单连接多流，解决队头阻塞）、头部压缩（HPACK）、服务端推送。</li><li>HTTP3：基于 QUIC（UDP），集成 TLS1.3、连接迁移、0-RTT；传输层也解决队头阻塞，抗丢包更强。</li></ul><h2 id="https-加密原理-tls-握手-★★★" tabindex="-1">HTTPS 加密原理；TLS 握手 ★★★ <a class="header-anchor" href="#https-加密原理-tls-握手-★★★" aria-label="Permalink to &quot;HTTPS 加密原理；TLS 握手 ★★★&quot;">​</a></h2><ul><li>HTTPS = HTTP + TLS/SSL；加密：非对称加密（RSA/ECDHE）交换密钥，对称加密（AES）加密数据；证书 + 数字签名保证身份；哈希保证完整性。</li><li>握手：客户端 Hello → 服务端证书 → 密钥协商（ECDHE）→ 生成会话密钥 → 完成，之后对称加密通信。</li></ul><h2 id="get-与-post-区别-★★★" tabindex="-1">GET 与 POST 区别 ★★★ <a class="header-anchor" href="#get-与-post-区别-★★★" aria-label="Permalink to &quot;GET 与 POST 区别 ★★★&quot;">​</a></h2><ul><li>GET 请求参数在 URL（有长度限制、可见、可缓存、书签）；POST 参数在请求体（更安全、可传大文件）。</li><li>语义上 GET 幂等读、POST 提交变更；实际底层都是 TCP，无本质区别。</li></ul><h2 id="cookie-session-token-区别-★★★" tabindex="-1">Cookie / Session / Token 区别 ★★★ <a class="header-anchor" href="#cookie-session-token-区别-★★★" aria-label="Permalink to &quot;Cookie / Session / Token 区别 ★★★&quot;">​</a></h2><ul><li>Cookie：浏览器存储的小文本，随请求发送，可被篡改、有大小限制。</li><li>Session：服务端存储的用户状态，客户端只存 sessionId（通常放 Cookie）；分布式需 Session 共享（Redis）。</li><li>Token：无状态凭证（JWT），服务端不存、靠签名校验，适合前后端分离/分布式；有泄露与撤销难的问题。</li></ul><h2 id="tcp-三次握手、四次挥手-为什么不能两次握手-★★★" tabindex="-1">TCP 三次握手、四次挥手；为什么不能两次握手 ★★★ <a class="header-anchor" href="#tcp-三次握手、四次挥手-为什么不能两次握手-★★★" aria-label="Permalink to &quot;TCP 三次握手、四次挥手；为什么不能两次握手 ★★★&quot;">​</a></h2><ul><li>三次握手：SYN → SYN+ACK → ACK，确认双方收发能力，同步初始序列号。</li><li>两次不行：无法确认客户端接收能力、无法防止历史/重复连接请求导致服务端半开连接。</li><li>四次挥手：FIN → ACK → FIN → ACK，因半关闭（被动方可能还有数据要发），比握手多一次；TIME_WAIT 等待 2MSL。</li></ul><h2 id="tcp-滑动窗口、拥塞控制-tcp-与-udp-区别-★★★" tabindex="-1">TCP 滑动窗口、拥塞控制；TCP 与 UDP 区别 ★★★ <a class="header-anchor" href="#tcp-滑动窗口、拥塞控制-tcp-与-udp-区别-★★★" aria-label="Permalink to &quot;TCP 滑动窗口、拥塞控制；TCP 与 UDP 区别 ★★★&quot;">​</a></h2><ul><li>滑动窗口：流量控制，接收方告知窗口大小；拥塞控制：慢启动、拥塞避免、快重传、快恢复，避免网络拥塞。</li><li>TCP 面向连接、可靠（重传/校验/排序）、字节流、有流量/拥塞控制；UDP 无连接、不可靠、报文、低延迟，适合音视频/游戏。</li></ul><h2 id="常见-http-状态码-★★☆" tabindex="-1">常见 HTTP 状态码 ★★☆ <a class="header-anchor" href="#常见-http-状态码-★★☆" aria-label="Permalink to &quot;常见 HTTP 状态码 ★★☆&quot;">​</a></h2><ul><li>1xx 信息、2xx 成功（200/201/204）、3xx 重定向（301 永久/302 临时/304 未修改）、4xx 客户端错误（400/401 未认证/403 无权限/404）、5xx 服务端错误（500/502 网关/503 不可用/504 超时）。</li></ul><h2 id="osi-七层-tcp-ip-四层模型-★★★" tabindex="-1">OSI 七层 / TCP/IP 四层模型 ★★★ <a class="header-anchor" href="#osi-七层-tcp-ip-四层模型-★★★" aria-label="Permalink to &quot;OSI 七层 / TCP/IP 四层模型 ★★★&quot;">​</a></h2><ul><li>OSI：物理、数据链路、网络、传输、会话、表示、应用；TCP/IP：链路、网络（IP）、传输（TCP/UDP）、应用（HTTP/DNS）。</li><li>常见设备与协议分层：交换机链路层、路由器网络层、TCP/UDP 传输层、HTTP/FTP/DNS 应用层。</li></ul><h2 id="输入-url-到页面展示全流程-★★★" tabindex="-1">输入 URL 到页面展示全流程 ★★★ <a class="header-anchor" href="#输入-url-到页面展示全流程-★★★" aria-label="Permalink to &quot;输入 URL 到页面展示全流程 ★★★&quot;">​</a></h2><ul><li>域名 → DNS 解析得 IP → 建立 TCP（HTTPS 再 TLS 握手）→ 发送 HTTP 请求 → 服务器处理返回 → 浏览器解析 HTML/CSS/JS → 构建 DOM/CSSOM → 渲染树 → 布局 → 绘制 → 合成。涉及缓存、连接复用、渲染优化。</li></ul><h2 id="dns-解析、session-共享、jwt-结构-★★★" tabindex="-1">DNS 解析、Session 共享、JWT 结构 ★★★ <a class="header-anchor" href="#dns-解析、session-共享、jwt-结构-★★★" aria-label="Permalink to &quot;DNS 解析、Session 共享、JWT 结构 ★★★&quot;">​</a></h2><ul><li>DNS：递归查询（本地缓存/hosts → 根/顶级/权威域名服务器）得到 IP，可 CDN 就近负载。</li><li>Session 共享：多实例下用 Redis 集中存储 Session（Spring Session）。</li><li>JWT：Header.Payload.Signature 三段 Base64；Payload 存声明（避免敏感信息），签名防篡改。</li></ul><h2 id="跨域-cors-原理与解决方案-前端转全栈必考-★★★" tabindex="-1">跨域 CORS 原理与解决方案（前端转全栈必考）★★★ <a class="header-anchor" href="#跨域-cors-原理与解决方案-前端转全栈必考-★★★" aria-label="Permalink to &quot;跨域 CORS 原理与解决方案（前端转全栈必考）★★★&quot;">​</a></h2><ul><li>同源策略：协议、域名、端口三者完全一致才算同源，否则「跨域」；浏览器为安全限制跨域脚本读取响应（请求能发出去，但响应被浏览器拦截）。</li><li>CORS（跨域资源共享）：由服务端在响应头声明允许，浏览器据此放行。核心头： <ul><li><code>Access-Control-Allow-Origin</code>：允许的来源（<code>*</code> 或具体域名）。</li><li><code>Access-Control-Allow-Methods</code>：允许的方法（GET/POST/PUT/DELETE 等）。</li><li><code>Access-Control-Allow-Headers</code>：允许的请求头。</li><li><code>Access-Control-Allow-Credentials</code>：是否允许携带 Cookie（配合 withCredentials）。</li></ul></li><li>简单请求 vs 预检请求：简单请求（GET/HEAD/POST + 特定 Content-Type 如 form）直接发；非简单请求（如 <code>Content-Type: application/json</code>、自定义头、PUT/DELETE）浏览器先发一个 OPTIONS 预检请求，服务端响应允许后才会发真正请求。</li><li>解决方案： <ul><li>后端：Spring 用 <code>@CrossOrigin</code> 注解或全局 <code>CorsFilter</code> / <code>WebMvcConfigurer</code> 配置 CORS 规则。</li><li>网关/Nginx：反向代理把前后端同源化（<code>/api</code> 转发到后端），或 Nginx 直接加 CORS 头。</li><li>JSONP：仅支持 GET、已基本淘汰。</li></ul></li><li>前端转全栈要能说清「为什么会有预检请求」「携带 Cookie 需要哪些配置」这两点。</li></ul>',24)]))}const u=l(t,[["render",s]]);export{P as __pageData,u as default};
